 CREATE OR REPLACE FUNCTION public.listintakedochistory(intakedocid uuid, skipno integer, pagesize integer)                                                                                                                                              
  RETURNS TABLE(totalcount bigint, intakenumber character varying, intakedocumentid uuid, documenttemplatekey character varying, versionno integer, documentpath character varying, insertedon timestamp without time zone, insertedby character varying)
  LANGUAGE plpgsql                                                                                                                                                                                                                                       
 AS $function$                                                                                                                                                                                                                                           
                                                                                                                                                                                                                                                         
 declare                                                                                                                                                                                                                                                 
 v_intakedocumentid uuid;                                                                                                                                                                                                                                
 v_documenttemplatekey character varying;                                                                                                                                                                                                                
 v_intakenumber character varying;                                                                                                                                                                                                                       
 v_versionno int;                                                                                                                                                                                                                                        
 BEGIN                                                                                                                                                                                                                                                   
         v_intakedocumentid:= intakedocid;                                                                                                                                                                                                               
                                                                                                                                                                                                                                                         
         Select id1.documenttemplatekey, id1.versionno, id1.intakenumber into v_documenttemplatekey, v_versionno, v_intakenumber from intakedocument id1 where id1.intakedocumentid = v_intakedocumentid;                                                
                                                                                                                                                                                                                                                         
     Return Query                                                                                                                                                                                                                                        
         Select count(1) over() totalcount, ido.intakenumber, ido.intakedocumentid, ido.documenttemplatekey, ido.versionno, ido.documentpath, ido.insertedon, up.fullname as insertedby                                                                  
         from intakedocument ido Left Join Userprofile up on up.securityusersid = ido.insertedby                                                                                                                                                         
         where ido.intakenumber = v_intakenumber and ido.documenttemplatekey = v_documenttemplatekey and ido.versionno < v_versionno                                                                                                                     
         order by ido.versionno desc                                                                                                                                                                                                                     
         limit pagesize offset skipno;                                                                                                                                                                                                                   
                                                                                                                                                                                                                                                         
 end;                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                         
 $function$                                                                                                                                                                                                                                              

